std::string_view Clip(Id id) {
    switch (id) {
        case Id::k_camera:
            return {reinterpret_cast<const char*>(k_camera), sizeof(k_camera)};
        case Id::k_overspeed:
            return {reinterpret_cast<const char*>(k_overspeed), sizeof(k_overspeed)};
        case Id::k_jam:
            return {reinterpret_cast<const char*>(k_jam), sizeof(k_jam)};
        case Id::k_gps_ok:
            return {reinterpret_cast<const char*>(k_gps_ok), sizeof(k_gps_ok)};
        case Id::k_leave_early:
            return {reinterpret_cast<const char*>(k_leave_early), sizeof(k_leave_early)};
        case Id::k_road_ok:
            return {reinterpret_cast<const char*>(k_road_ok), sizeof(k_road_ok)};
    }
    return {};
}

